@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Oswald:wght@500;700&display=swap');
@import url('https://cdn.jsdelivr.net/npm/remixicon@4.1.0/fonts/remixicon.css');

:root {
  --bg-color: #111111;
  --bg-light: #1e1e1e;
  --bg-card: #222222;
  --text-color: #FFFFFF;
  --text-muted: #A0A0A0;
  --primary-color: #E63946;
  --primary-hover: #D62828;
  --border-color: #333333;
}

* {
  box-sizing: border-box;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  margin: 0;
  padding: 0;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Oswald', sans-serif;
  text-transform: uppercase;
  margin-top: 0;
  margin-bottom: 1rem;
  line-height: 1.1;
}

a {
  color: var(--text-color);
  text-decoration: none;
  transition: color 0.3s;
}

a:hover {
  color: var(--primary-color);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Typography Classes */
.text-primary { color: var(--primary-color); }
.text-center { text-align: center; }
.display-1 { font-size: 5rem; font-weight: 700; letter-spacing: 2px; }
.display-2 { font-size: 3.5rem; font-weight: 700; }
.display-3 { font-size: 2.5rem; font-weight: 700; }
.lead { font-size: 1.25rem; color: var(--text-muted); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1rem 2rem;
  font-family: 'Oswald', sans-serif;
  font-size: 1.125rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  border: none;
  border-radius: 2px;
  transition: all 0.3s ease;
  text-decoration: none;
}

.btn-primary {
  background-color: var(--primary-color);
  color: #fff;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
  color: #fff;
}

.btn-outline {
  background-color: transparent;
  color: #fff;
  border: 2px solid #fff;
}

.btn-outline:hover {
  background-color: #fff;
  color: #000;
}

.btn-block {
  width: 100%;
}

/* Sections */
section {
  padding: 6rem 0;
}

.section-darker { background-color: var(--bg-light); }

/* Navbar */
.navbar {
  position: fixed;
  top: 0;
  width: 100%;
  background-color: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 0;
}

.navbar .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.navbar-brand {
  font-family: 'Oswald', sans-serif;
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
  letter-spacing: 2px;
}

.navbar-nav {
  display: flex;
  gap: 2rem;
  list-style: none;
  margin: 0;
  padding: 0;
  align-items: center;
}

.nav-item {
  font-size: 0.875rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: #fff;
  font-size: 2rem;
  cursor: pointer;
}

/* Hero Sections */
.hero {
  height: 90vh;
  min-height: 600px;
  display: flex;
  align-items: center;
  background-color: var(--bg-light);
  background-size: cover;
  background-position: center;
  position: relative;
  text-align: center;
  padding-top: 80px; /* Offset for navbar */
}

.hero::before {
  content: '';
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  background: linear-gradient(to bottom, rgba(17,17,17,0.4), rgba(17,17,17,0.9));
}

.hero-content {
  position: relative;
  z-index: 10;
  max-width: 900px;
  margin: 0 auto;
}

.hero-cta {
  margin-top: 2rem;
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Layout Utilities */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2rem; }

/* Image placeholder styling */
.img-placeholder {
  background-color: var(--bg-card);
  width: 100%;
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  border-radius: 4px;
}

/* Footer */
footer {
  background-color: var(--bg-color);
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
}

.footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-muted);
}

.footer-col a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid var(--border-color);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

/* Newsletter */
.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 2rem auto 0;
}

.newsletter-form input {
  flex: 1;
  padding: 1rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  color: #fff;
  font-size: 1rem;
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--primary-color);
}

.form-feedback {
  margin-top: 0.5rem;
  font-size: 0.875rem;
}
.feedback-error { color: var(--primary-color); }
.feedback-success { color: #4CAF50; }

/* Carousel */
.carousel-wrapper {
  position: relative;
  overflow: hidden;
  margin-top: 3rem;
}

.carousel-track {
  display: flex;
  transition: transform 0.4s ease-in-out;
}

.carousel-slide {
  min-width: 100%;
  padding: 0 1rem;
}

.carousel-content {
  background-color: var(--bg-card);
  aspect-ratio: 21/9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--text-muted);
  border-radius: 8px;
}

.carousel-controls {
  display: flex;
  justify-content: space-between;
  position: absolute;
  top: 50%;
  left: 0; right: 0;
  transform: translateY(-50%);
  pointer-events: none;
}

.carousel-btn {
  background-color: rgba(0,0,0,0.5);
  color: #fff;
  border: none;
  width: 50px; height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  cursor: pointer;
  pointer-events: auto;
  transition: background-color 0.3s;
  margin: 0 1rem;
}

.carousel-btn:hover {
  background-color: var(--primary-color);
}

/* Instructor Grid */
.filters {
  display: flex;
  gap: 1rem;
  margin-bottom: 3rem;
  justify-content: center;
  flex-wrap: wrap;
}

.filter-btn {
  background: transparent;
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 0.5rem 1.5rem;
  border-radius: 20px;
  cursor: pointer;
  font-family: 'Inter', sans-serif;
  transition: all 0.3s;
}

.filter-btn.active, .filter-btn:hover {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

.instructor-card {
  background: var(--bg-card);
  border-radius: 8px;
  overflow: hidden;
  transition: transform 0.3s;
}

.instructor-card:hover {
  transform: translateY(-5px);
}

.instructor-img {
  aspect-ratio: 3/4;
  background-color: var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
}

.instructor-info {
  padding: 1.5rem;
  text-align: center;
}

.instructor-info h3 { margin-bottom: 0.25rem; }
.instructor-info p { color: var(--text-muted); margin-bottom: 1rem; font-size: 0.875rem; }

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  color: #fff;
  font-family: 'Oswald', sans-serif;
  font-size: 1.25rem;
  text-transform: uppercase;
  text-align: left;
  padding: 1.5rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
}

.faq-question i {
  transition: transform 0.3s;
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-muted);
}

.faq-item.active .faq-answer {
  max-height: 200px; /* Adjust based on content */
  padding-bottom: 1.5rem;
}

.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

/* Floor vs Treadmill Toggle */
.workout-toggle {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.toggle-btn {
  background: transparent;
  color: var(--text-muted);
  border: none;
  font-family: 'Oswald', sans-serif;
  font-size: 2rem;
  text-transform: uppercase;
  cursor: pointer;
  padding: 0.5rem 1rem;
  position: relative;
}

.toggle-btn.active {
  color: #fff;
}

.toggle-btn.active::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background-color: var(--primary-color);
}

.workout-content {
  display: none;
  animation: fadeIn 0.5s;
}

.workout-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}

.schedule-table th, .schedule-table td {
  padding: 1.5rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.schedule-table th {
  font-family: 'Oswald', sans-serif;
  font-size: 1.25rem;
  color: var(--text-muted);
}

.schedule-table tr:hover td {
  background-color: rgba(255,255,255,0.02);
}

.schedule-table td:first-child {
  font-family: 'Oswald', sans-serif;
  font-size: 1.25rem;
  color: #fff;
}

/* Top Bar Promo */
.top-bar {
  background-color: var(--primary-color);
  color: #fff;
  text-align: center;
  padding: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  position: relative;
  z-index: 1001;
}

.top-bar a {
  color: #fff;
  text-decoration: underline;
  margin-left: 0.5rem;
}

/* Responsive */
@media (max-width: 992px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .navbar-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background-color: var(--bg-color);
    flex-direction: column;
    padding: 2rem 0;
    border-bottom: 1px solid var(--border-color);
  }
  .navbar-nav.active { display: flex; }
  .nav-toggle { display: block; }
  .display-1 { font-size: 3rem; }
  .display-2 { font-size: 2.5rem; }
  .footer-grid { grid-template-columns: 1fr; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Menu Toggle
  const navToggle = document.getElementById('nav-toggle');
  const navMenu = document.getElementById('navbar-nav');
  if (navToggle && navMenu) {
    navToggle.addEventListener('click', () => {
      navMenu.classList.toggle('active');
    });
  }

  // Newsletter Validation
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('input[type="email"]');
      const feedback = form.querySelector('.form-feedback') || document.createElement('div');

      if (!form.querySelector('.form-feedback')) {
        feedback.className = 'form-feedback';
        form.appendChild(feedback);
      }

      const email = input.value.trim();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (!email) {
        feedback.textContent = 'Please enter an email address.';
        feedback.className = 'form-feedback feedback-error';
      } else if (!emailRegex.test(email)) {
        feedback.textContent = 'Please enter a valid email address.';
        feedback.className = 'form-feedback feedback-error';
      } else {
        feedback.textContent = 'Thank you for subscribing!';
        feedback.className = 'form-feedback feedback-success';
        input.value = '';
      }
    });
  });

  // Carousel
  const track = document.getElementById('carousel-track');
  if (track) {
    const prevBtn = document.getElementById('carousel-prev');
    const nextBtn = document.getElementById('carousel-next');
    const slides = Array.from(track.children);
    let currentIndex = 0;

    function updateCarousel() {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    }

    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        currentIndex = (currentIndex + 1) % slides.length;
        updateCarousel();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', () => {
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        updateCarousel();
      });
    }

    // Optional: Swipe support
    let touchStartX = 0;
    let touchEndX = 0;

    track.addEventListener('touchstart', e => {
      touchStartX = e.changedTouches[0].screenX;
    }, {passive: true});

    track.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      if (touchStartX - touchEndX > 50) {
        // Swipe left
        currentIndex = (currentIndex + 1) % slides.length;
        updateCarousel();
      } else if (touchEndX - touchStartX > 50) {
        // Swipe right
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        updateCarousel();
      }
    }, {passive: true});
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  if (faqItems.length > 0) {
    faqItems.forEach(item => {
      const question = item.querySelector('.faq-question');
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all
        faqItems.forEach(faq => faq.classList.remove('active'));

        // Toggle current
        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }

  // Instructor Filter
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorCards = document.querySelectorAll('.instructor-card');
  if (filterBtns.length > 0 && instructorCards.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Update active class
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const filterValue = btn.getAttribute('data-filter');

        instructorCards.forEach(card => {
          if (filterValue === 'all' || card.getAttribute('data-location') === filterValue) {
            card.style.display = 'block';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });
  }

  // Workout Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const workoutContents = document.querySelectorAll('.workout-content');
  if (toggleBtns.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-target');

        toggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        workoutContents.forEach(content => {
          if (content.id === target) {
            content.classList.add('active');
          } else {
            content.classList.remove('active');
          }
        });
      });
    });
  }

  // Country Selector (Footer)
  const countrySelect = document.getElementById('country-select');
  if (countrySelect) {
    // A simple mock for country selection interaction
    countrySelect.addEventListener('change', (e) => {
      console.log('Country changed to: ' + e.target.value);
    });
  }
});
